                    tableClone.style.fontSize = '10px';
                    tableClone.style.marginTop = '0';
                    tableClone.style.paddingTop = '0';
                    
                    // Style headers
                    tableClone.querySelectorAll('th').forEach(th => {
                        th.style.padding = '8px';
                        th.style.backgroundColor = '#0078d4';
                        th.style.color = 'white';
