        // Export current view to PDF using html2pdf
        async function exportToPDF() {
            const button = document.querySelector('.export-pdf-btn');
            button.disabled = true;
            button.textContent = '📄 Generating PDF...';

            try {
                // Get current report name
                const selector = document.getElementById('reportSelector');
                const reportName = selector.options[selector.selectedIndex].text;
                const fileName = `Vulnerability_Dashboard_${reportName.replace(/\s+/g, '_')}_${new Date().toISOString().split('T')[0]}.pdf`;

                // Get the elements to include in PDF
                const container = document.querySelector('.container');
                const activeSection = document.querySelector('.report-section.active');

                // Clone the container
                const cloneContainer = document.createElement('div');
                cloneContainer.style.backgroundColor = 'white';
                cloneContainer.style.padding = '20px';
                cloneContainer.style.fontFamily = 'Arial, sans-serif';
                
                // Add title
                const title = document.createElement('h1');
                title.textContent = `🛡️ Vulnerability Dashboard - ${reportName}`;
                title.style.fontSize = '28px';
                title.style.color = '#0078d4';
                title.style.marginBottom = '20px';
                cloneContainer.appendChild(title);

                // Add stats summary
                const statsClone = container.querySelector('.stats-summary').cloneNode(true);
                cloneContainer.appendChild(statsClone);

                // Clone and add chart
                const chartContainer = activeSection.querySelector('.chart-container');
                if (chartContainer) {
                    const chartClone = chartContainer.cloneNode(true);
                    const canvas = chartContainer.querySelector('canvas');
                    const clonedCanvas = chartClone.querySelector('canvas');
                    
                    if (canvas && clonedCanvas) {
                        // Convert canvas to image
                        const imgData = canvas.toDataURL('image/png');
                        const img = document.createElement('img');
                        img.src = imgData;
                        img.style.width = '100%';
                        img.style.height = 'auto';
                        img.style.display = 'block';
                        img.style.margin = '0';
                        img.style.padding = '0';
                        
                        clonedCanvas.parentNode.replaceChild(img, clonedCanvas);
                    }
                    
                    chartClone.style.background = 'white';
                    chartClone.style.marginBottom = '20px';
                    chartClone.style.marginTop = '0';
                    chartClone.style.paddingBottom = '0';
                    chartClone.style.paddingTop = '0';
                    chartClone.style.height = 'auto';
                    chartClone.style.minHeight = '0';
                    cloneContainer.appendChild(chartClone);
                }

                // Add table with clean styling
                const table = activeSection.querySelector('table');
                if (table) {
                    const tableClone = table.cloneNode(true);
                    tableClone.style.width = '100%';
                    tableClone.style.borderCollapse = 'collapse';
                    tableClone.style.fontSize = '10px';
                    tableClone.style.marginTop = '0';
                    tableClone.style.paddingTop = '0';
                    
                    // Style headers
                    tableClone.querySelectorAll('th').forEach(th => {
                        th.style.padding = '8px';
                        th.style.backgroundColor = '#0078d4';
                        th.style.color = 'white';
                        th.style.border = '1px solid #ddd';
                        th.style.fontWeight = 'bold';
                        th.style.textAlign = 'left';
                    });
                    
                    // Style cells with alternating colors
                    const rows = tableClone.querySelectorAll('tbody tr');
                    rows.forEach((row, idx) => {
                        row.style.pageBreakInside = 'avoid';
                        row.querySelectorAll('td').forEach(td => {
                            td.style.padding = '8px';
                            td.style.border = '1px solid #ddd';
                            td.style.backgroundColor = idx % 2 === 0 ? '#f9f9f9' : 'white';
                        });
                    });
                    
                    cloneContainer.appendChild(tableClone);
                }

                // Configure PDF options
                const opt = {
                    margin: 10,
                    filename: fileName,
                    image: { type: 'jpeg', quality: 0.98 },
                    html2canvas: { 
                        scale: 2,
                        logging: false,
                        useCORS: true,
                        backgroundColor: '#ffffff'
                    },
                    jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
                    pagebreak: { mode: 'avoid-all', before: '.page-break' }
                };

                // Generate PDF
                html2pdf().set(opt).from(cloneContainer).save().then(() => {
                    button.disabled = false;
                    button.textContent = '📄 Export to PDF';
                }).catch(err => {
                    console.error('PDF generation failed:', err);
                    alert('Failed to generate PDF: ' + err.message);
                    button.disabled = false;
                    button.textContent = '📄 Export to PDF';
